    eq(listOf("2026-02-13T00:00:00Z", "2026-03-13T00:00:00Z", "2026-11-13T00:00:00Z"), RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=MONTHLY;BYDAY=FR;BYMONTHDAY=13;COUNT=3"), "rrule FREQ=MONTHLY;BYDAY=FR;BYMONTHDAY=13;COUNT=3")
