    eq(listOf("2026-01-31T10:00:00Z", "2026-02-28T10:00:00Z", "2026-03-31T10:00:00Z", "2026-04-30T10:00:00Z"), RRule.expandRRule("2026-01-01T10:00:00Z", "FREQ=YEARLY;BYMONTHDAY=-1;COUNT=4"), "rrule FREQ=YEARLY;BYMONTHDAY=-1;COUNT=4")
    eq(listOf("2026-06-01T10:00:00Z", "2026-06-15T10:00:00Z", "2027-06-01T10:00:00Z", "2027-06-15T10:00:00Z"), RRule.expandRRule("2026-03-05T10:00:00Z", "FREQ=YEARLY;BYMONTHDAY=1,15;BYMONTH=6;COUNT=4"), "rrule FREQ=YEARLY;BYMONTHDAY=1,15;BYMONTH=6;COUNT=4")
    eq(listOf("2026-01-05T08:00:00Z", "2026-01-12T08:00:00Z", "2026-01-19T08:00:00Z", "2026-01-26T08:00:00Z", "2026-07-06T08:00:00Z", "2026-07-13T08:00:00Z"), RRule.expandRRule("2026-01-05T08:00:00Z", "FREQ=WEEKLY;BYMONTH=1,7;BYDAY=MO;COUNT=6"), "rrule FREQ=WEEKLY;BYMONTH=1,7;BYDAY=MO;COUNT=6")
    eq(listOf("2026-01-01T08:00:00Z", "2026-01-31T08:00:00Z", "2026-02-01T08:00:00Z", "2026-02-28T08:00:00Z", "2026-03-01T08:00:00Z"), RRule.expandRRule("2026-01-01T08:00:00Z", "FREQ=DAILY;BYMONTHDAY=1,-1;COUNT=5"), "rrule FREQ=DAILY;BYMONTHDAY=1,-1;COUNT=5")
    eq(listOf("2028-02-29T08:00:00Z", "2032-02-29T08:00:00Z"), RRule.expandRRule("2026-01-01T08:00:00Z", "FREQ=DAILY;BYMONTH=2;BYMONTHDAY=29;COUNT=2"), "rrule FREQ=DAILY;BYMONTH=2;BYMONTHDAY=29;COUNT=2")
    eq(listOf("2026-06-20T08:00:00Z", "2026-12-20T08:00:00Z", "2027-06-20T08:00:00Z", "2027-12-20T08:00:00Z"), RRule.expandRRule("2026-05-20T08:00:00Z", "FREQ=MONTHLY;BYMONTH=6,12;COUNT=4"), "rrule FREQ=MONTHLY;BYMONTH=6,12;COUNT=4")
    eq(listOf("2026-03-02T08:00:00Z", "2026-03-09T08:00:00Z", "2026-03-16T08:00:00Z", "2026-03-23T08:00:00Z", "2026-03-30T08:00:00Z"), RRule.expandRRule("2026-01-31T08:00:00Z", "FREQ=MONTHLY;BYDAY=MO;BYMONTH=3;COUNT=5"), "rrule FREQ=MONTHLY;BYDAY=MO;BYMONTH=3;COUNT=5")
