    eq(listOf("2026-10-17T09:00:00Z", "2026-10-18T09:00:00Z", "2026-10-24T09:00:00Z", "2026-10-25T09:00:00Z", "2026-10-31T09:00:00Z", "2026-11-01T09:00:00Z"), RRule.expandRRule("2026-10-12T09:00:00Z", "FREQ=WEEKLY;BYDAY=SA,SU;UNTIL=20261101T090000Z"), "rrule FREQ=WEEKLY;BYDAY=SA,SU;UNTIL=20261101T090000Z")
