    throwsIae("invalid FREQ=DAILY;BYDAY=1MO") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY;BYDAY=1MO") }
    throwsIae("invalid FREQ=MONTHLY;BYMONTHDAY=32") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=MONTHLY;BYMONTHDAY=32") }
    throwsIae("invalid FREQ=MONTHLY;BYMONTHDAY=0") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=MONTHLY;BYMONTHDAY=0") }
    throwsIae("invalid FREQ=MONTHLY;BYSETPOS=1") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=MONTHLY;BYSETPOS=1") }
    throwsIae("invalid FREQ=WEEKLY;WKST=MO") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=WEEKLY;WKST=MO") }
    throwsIae("invalid FREQ=WEEKLY;INTERVAL=0") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=WEEKLY;INTERVAL=0") }
    throwsIae("invalid FREQ=WEEKLY;INTERVAL=-1") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=WEEKLY;INTERVAL=-1") }
    throwsIae("invalid FREQ=MONTHLY;BYDAY=6MO") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=MONTHLY;BYDAY=6MO") }
    throwsIae("invalid FREQ=YEARLY;BYMONTH=1;BYDAY=6MO") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=YEARLY;BYMONTH=1;BYDAY=6MO") }
    throwsIae("invalid FREQ=YEARLY;BYDAY=54MO") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=YEARLY;BYDAY=54MO") }
    throwsIae("invalid FREQ=MONTHLY;BYDAY=0MO") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=MONTHLY;BYDAY=0MO") }
    throwsIae("invalid FREQ=MONTHLY;BYDAY=MO,1TU") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=MONTHLY;BYDAY=MO,1TU") }
    throwsIae("invalid FREQ=YEARLY;BYMONTH=13") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=YEARLY;BYMONTH=13") }
    throwsIae("invalid FREQ=YEARLY;BYMONTH=-1") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=YEARLY;BYMONTH=-1") }
    throwsIae("invalid FREQ=YEARLY;UNTIL=2026-12-31") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=YEARLY;UNTIL=2026-12-31") }
    throwsIae("invalid FREQ=DAILY;FREQ=DAILY") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY;FREQ=DAILY") }
    throwsIae("invalid FREQ=WEEKLY;BYDAY=XX") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=WEEKLY;BYDAY=XX") }
    throwsIae("invalid FREQ=DAILY;BYHOUR=9") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY;BYHOUR=9") }
    eq(true, RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY;BYDAY=MO", 3).isNotEmpty(), "DAILY with BYDAY parses")
    eq(true, RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=MONTHLY;BYDAY=MO;BYMONTHDAY=1", 3).isNotEmpty(), "BYDAY with BYMONTHDAY parses")
    eq(true, RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=YEARLY;BYDAY=20MO", 3).isNotEmpty(), "YEARLY ordinal BYDAY parses")
    eq(emptyList<String>(), RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY;BYMONTH=2;BYMONTHDAY=30;COUNT=1"), "impossible rule is empty")
    eq(3, RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY", 3).size, "limit")
    eq(50, RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY").size, "default limit")
    throwsIae("limit too large") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY", 1001) }
    throwsIae("limit zero") { RRule.expandRRule("2026-01-01T00:00:00Z", "FREQ=DAILY", 0) }
    throwsIae("bad dtstart") { RRule.expandRRule("2026-02-30T00:00:00Z", "FREQ=DAILY") }
    throwsIae("dtstart format") { RRule.expandRRule("2026-01-01 00:00:00", "FREQ=DAILY") }

    println("RRuleTest: $passed passed, $failed failed")
    if (failed > 0) exitProcess(1)
}
